{
  "intent": "check_and_fix",
  "intent_description": "Restore the down Serial0/1/0 link between router1 and router2 so the serial adjacency is UP. Impact: loss of layer-3 connectivity between the two routers on 10.0.0.0/30. Desired outcome: both ends show admin up and oper up on Serial0/1/0 and normal OSPF/adjacency can resume.",
  "target": "router2 Serial0/1/0",
  "diagnosis": {
    "initial_alert": "R1 Serial0/1/0 oper changed from up -> lower-layer-down (admin up). R2 Serial0/1/0 oper changed from up -> down (admin down).",
    "root_causes": [
      {
        "type": "administrative_shutdown",
        "cause": "Serial0/1/0 on router2 was administratively shutdown, causing the link to go down and the neighbor (router1) to report lower-layer-down.",
        "evidence": [
          "Pre-remediation get_interface_status on router2 Serial0/1/0: admin_state = \"down\", oper_state = \"down\"",
          "Running config for router2: Serial0/1/0 interface stanza contains \"shutdown\" (administratively down)",
          "Pre-remediation get_interface_status on router1 Serial0/1/0: admin_state = \"up\", oper_state = \"lower-layer-down\"",
          "Running config for router1: Serial0/1/0 configured with IP 10.0.0.1/30 and description \"Link to R2\" indicating this is the point-to-point link between R1 and R2"
        ],
        "confidence": 0.95
      }
    ],
    "missing_info": [
      "Reason why router2 Serial0/1/0 was administratively shut (operator action, automation, or policy) is not present in device state or logs."
    ]
  },
  "needs_fix": true,
  "plan": {
    "plan_steps": [
      {
        "id": "step1",
        "device": "router2",
        "action": "set_interface_state",
        "target": "Serial0/1/0",
        "parameters": {
          "state": "up"
        }
      }
    ]
  },
  "changes": [
    {
      "phase": "remediation",
      "tool": "set_interface_state",
