          "speed": "2064384",
          "duplex": null,
          "phys_address": "ac:3a:67:20:33:70",
          "last_change": "2026-06-02T14:32:45.00031+00:00",
          "input_errors": 0,
          "output_errors": 0,
          "crc_errors": null,
          "drops": 0,
          "bandwidth_utilization": null
        },
        "verifies": "router2 interface was brought administratively up and is now operationally up"
      },
      {
        "tool": "get_interface_status",
        "device": "router1",
        "target": "Serial0/1/0",
        "result": {
          "admin_state": "up",
          "oper_state": "up",
          "speed": "2048000",
          "duplex": null,
          "phys_address": "ac:3a:67:20:22:90",
          "last_change": "2026-06-02T14:32:53.00076+00:00",
          "input_errors": 0,
          "output_errors": 0,
          "crc_errors": null,
          "drops": 0,
          "bandwidth_utilization": null
        },
        "verifies": "neighbor (router1) oper_state recovered to up"
      }
    ],
    "missing_info": []
  },
  "final_summary": "The serial link between router1 and router2 (Serial0/1/0) was down because router2 had the interface administratively shutdown. I enabled Serial0/1/0 on router2. Post-change checks show both ends now admin up and oper up. The link is restored; root cause of the admin shutdown is unknown.",
